import os
import unittest

from robot_pet import RobotPet


def make_pet():
    try:
        return RobotPet("Robo")
    except TypeError:
        return RobotPet()


CLASS_HEADER = (
    "class TestRobotPet(unittest.TestCase):\n"
    "    def setUp(self):\n"
    "        self.pet = make_pet()\n"
)

HERE = os.path.dirname(os.path.abspath(__file__))
with open(os.path.join(HERE, "unit_tests_that_change_state.py")) as source:
    test_methods = source.read()

namespace = {"unittest": unittest, "make_pet": make_pet}
exec(CLASS_HEADER + test_methods, namespace)

TestRobotPet = namespace["TestRobotPet"]

if __name__ == "__main__":
    unittest.main(argv=["run_tests"], verbosity=2, exit=False)
